int countHouses(const vector<int>& houses, int d, int c) {
    if (houses.empty()) return 0;
    int cnt = 1;
    int prev = houses[0];
    for (size_t i = 1; i < houses.size(); i++) {
        if (cnt >= c) return cnt;
        if (houses[i] - prev >= d) { prev = houses[i]; cnt++; }
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, c;
