    sort(houses.begin(), houses.end());
    int lo = 1, hi = houses[n-1] - houses[0], ans = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (countHouses(houses, mid, c) >= c) { ans = mid; lo = mid + 1; }
        else hi = mid - 1;
    }
    cout << ans << "\n";
    return 0;
}
